from typing import Any
from app.models import Node, Relationship


class ContextBuilder:
    def build(self, node: Node, question: str, previous_responses: list[dict[str, Any]], relationships: list[Relationship]) -> dict[str, Any]:
        # `relationships` must have `.protocols` already
        # eager-loaded (selectinload) by the caller — async
        # SQLAlchemy cannot lazily load it here.
        applicable_protocols = []
        for rel in relationships:
            for p in rel.protocols:
                applicable_protocols.append({
                    "protocol_id": p.id,
                    "name": p.name,
                    "confidentiality": p.confidentiality,
                    "allowed_information_types": p.allowed_information_types or [],
                })

        return {
            "node_name": node.name,
            "question": question,
            "role": node.role,
            "title": node.title,
            "responsibilities": node.responsibilities or [],
            "decision_rights": node.decision_rights or [],
            "relevant_relationship_ids": [r.id for r in relationships],
            "applicable_protocols": applicable_protocols,
        }

from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Any
from app.models import Relationship, RelationshipDirection, Protocol


def utcnow() -> datetime:
    return datetime.now(timezone.utc)


@dataclass(slots=True)
class RoutingDecision:
    from_node: str
    to_node: str
    allowed: bool
    reason: str
    relationship_id: str | None = None
    protocol_id: str | None = None
    timestamp: datetime = field(default_factory=utcnow)


class GraphRouter:
    def get_candidates(self, node_id: str, relationships: list[Relationship]) -> list[tuple[Relationship, str]]:
        candidates: list[tuple[Relationship, str]] = []
        for rel in relationships:
            if rel.source_node_id == node_id and rel.direction in (RelationshipDirection.FORWARD, RelationshipDirection.BIDIRECTIONAL):
                candidates.append((rel, rel.target_node_id))
            elif rel.target_node_id == node_id and rel.direction in (RelationshipDirection.REVERSE, RelationshipDirection.BIDIRECTIONAL):
                candidates.append((rel, rel.source_node_id))
        return candidates

    def evaluate(self, source_node_id: str, target_node_id: str, relationship: Relationship, protocols: list[Protocol], info_type: str | None = None) -> RoutingDecision:
        if not protocols:
            return RoutingDecision(source_node_id, target_node_id, True, "No protocol restriction configured.", relationship.id, None, utcnow())

        # A relationship can now carry more than one
        # protocol; communication is allowed only if every
        # attached protocol allows it (AND semantics). This
        # is a direct generalization of the previous
        # single-protocol behavior — with 0 or 1 protocols
        # attached, the result is identical to before.
        # `protocol_id` on the decision reflects whichever
        # protocol blocked it, or the first protocol
        # evaluated if all of them allow it.
        for protocol in protocols:
            if not protocol.can_send:
                return RoutingDecision(source_node_id, target_node_id, False, "Protocol blocks sending.", relationship.id, protocol.id, utcnow())
            if not protocol.can_receive:
                return RoutingDecision(source_node_id, target_node_id, False, "Protocol blocks receiving.", relationship.id, protocol.id, utcnow())
            if protocol.allowed_targets and target_node_id not in protocol.allowed_targets:
                return RoutingDecision(source_node_id, target_node_id, False, "Target is not allowed by protocol.", relationship.id, protocol.id, utcnow())
            if info_type and protocol.allowed_information_types and info_type not in protocol.allowed_information_types:
                return RoutingDecision(source_node_id, target_node_id, False, "Information type is not allowed by protocol.", relationship.id, protocol.id, utcnow())

        return RoutingDecision(source_node_id, target_node_id, True, "Relationship direction and all attached protocols allow communication.", relationship.id, protocols[0].id, utcnow())

from dataclasses import dataclass, field
from typing import Iterable
from app.models import Node, Relationship, Protocol


@dataclass
class ValidationResult:
    valid: bool
    errors: list[str] = field(default_factory=list)
    warnings: list[str] = field(default_factory=list)


class GraphValidator:
    def validate(self, nodes: Iterable[Node], relationships: Iterable[Relationship], protocols: Iterable[Protocol]) -> ValidationResult:
        nodes = list(nodes)
        relationships = list(relationships)
        protocols = list(protocols)
        errors: list[str] = []
        warnings: list[str] = []

        node_ids = [n.id for n in nodes]
        if len(node_ids) != len(set(node_ids)):
            errors.append("Duplicate node IDs detected.")
        node_set = set(node_ids)
        protocol_set = {p.id for p in protocols}

        for node in nodes:
            if node.parent_id and node.parent_id not in node_set:
                errors.append(f"Node {node.id} has invalid parent reference {node.parent_id}.")
            if node.parent_id == node.id:
                errors.append(f"Node {node.id} cannot be its own parent.")

        for rel in relationships:
            if rel.source_node_id not in node_set:
                errors.append(f"Relationship {rel.id} has invalid source node {rel.source_node_id}.")
            if rel.target_node_id not in node_set:
                errors.append(f"Relationship {rel.id} has invalid target node {rel.target_node_id}.")
            if rel.source_node_id == rel.target_node_id:
                errors.append(f"Relationship {rel.id} cannot connect a node to itself.")
            # `rel.protocols` must already be eager-loaded
            # (selectinload) by the caller.
            for protocol in rel.protocols:
                if protocol.id not in protocol_set:
                    errors.append(f"Relationship {rel.id} references protocol {protocol.id} that is not part of this graph.")

        # Hierarchy cycles only; communication relationship cycles are valid.
        parent_map = {n.id: n.parent_id for n in nodes if n.parent_id}
        for node_id in parent_map:
            seen: set[str] = set()
            current = node_id
            while current in parent_map:
                if current in seen:
                    errors.append(f"Hierarchy cycle detected involving node {node_id}.")
                    break
                seen.add(current)
                current = parent_map[current]  # type: ignore[index]

        if nodes:
            roots = [n for n in nodes if n.parent_id is None]
            if len(roots) > 1:
                warnings.append(f"Hierarchy has {len(roots)} root-level nodes.")

        return ValidationResult(valid=not errors, errors=errors, warnings=warnings)

