@import "tailwindcss";

:root {
  --background: #0a0a0a;
  --surface: #111111;
  --surface-2: #161616;
  --surface-3: #1c1c1c;

  --border: #292929;
  --border-light: #333333;

  --text: #f5f5f5;
  --text-secondary: #a1a1a1;
  --text-muted: #666666;

  --accent: #ffffff;
  --success: #4ade80;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;

  width: 100%;
  height: 100%;

  overflow: hidden;
}

body {
  background: var(--background);
  color: var(--text);

  font-family:
    Arial,
    Helvetica,
    sans-serif;
}

button,
input,
textarea,
select {
  font: inherit;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
}


/* =========================================================
   APP SHELL
========================================================= */

.app-shell {
  position: relative;

  display: flex;

  width: 100%;
  height: 100vh;
  height: 100dvh;

  overflow: hidden;

  background: var(--background);
}


/* =========================================================
   SIDEBAR
========================================================= */

.sidebar {
  position: relative;
  z-index: 100;

  flex-shrink: 0;

  width: 240px;
  min-width: 240px;
  height: 100vh;

  display: flex;
  flex-direction: column;

  background: #0d0d0d;

  border-right: 1px solid var(--border);

  padding: 20px 14px;

  transition:
    width 0.18s ease,
    min-width 0.18s ease,
    padding 0.18s ease;

  pointer-events: auto;
}

.sidebar-collapsed {
  width: 60px;
  min-width: 60px;

  padding: 20px 8px;
}

/* Mobile drawer backdrop — only rendered while the
   sidebar is open on a mobile-width viewport. */
.sidebar-backdrop {
  position: fixed;
  inset: 0;

  z-index: 900;

  background: rgba(0, 0, 0, 0.6);
}

/* Hamburger button that opens the mobile drawer.
   Hidden on desktop; the RESPONSIVE section below
   reveals it under the mobile breakpoint. */
.mobile-menu-button {
  display: none;

  align-items: center;
  justify-content: center;

  width: 26px;
  height: 26px;
  flex-shrink: 0;
  margin: 0 -2px 0 -4px;

  border: 0;
  border-radius: 6px;

  background: transparent;
  color: #999;

  pointer-events: auto;
}

.mobile-menu-button:hover {
  background: #1d1d1d;
  color: #eee;
}

.sidebar-toggle {
  position: absolute;
  top: 22px;
  right: -11px;

  z-index: 101;

  width: 22px;
  height: 22px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid var(--border-light);
  border-radius: 50%;

  background: #171717;
  color: #999;

  transition:
    background 0.15s ease,
    color 0.15s ease;

  pointer-events: auto;
}

.sidebar-toggle:hover {
  background: #222;
  color: #eee;
}

.sidebar-collapsed .sidebar-logo,
.sidebar-collapsed .new-graph-button,
.sidebar-collapsed .sidebar-nav-item {
  justify-content: center;
}

.sidebar-collapsed .backend-status {
  justify-content: center;
}

.sidebar-logo {
  display: flex;
  align-items: center;
  gap: 11px;

  padding: 4px 8px 26px;
}

.logo-mark {
  width: 34px;
  height: 34px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid #3a3a3a;
  border-radius: 9px;

  background: #171717;
}

.logo-title {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.logo-subtitle {
  margin-top: 2px;

  color: var(--text-muted);

  font-size: 10px;
  letter-spacing: 0.04em;
}


/* =========================================================
   SIDEBAR SECTION
========================================================= */

.sidebar-section {
  padding: 0 6px 18px;
}

.sidebar-section-title {
  margin-bottom: 10px;

  color: #555;

  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
}

.new-graph-button {
  width: 100%;
  height: 36px;

  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;

  border: 1px solid var(--border-light);
  border-radius: 7px;

  background: #181818;
  color: #ddd;

  font-size: 12px;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;

  pointer-events: auto;
}

.new-graph-button:hover {
  background: #222;
  border-color: #444;
}


/* =========================================================
   NAVIGATION
========================================================= */

.sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 3px;

  pointer-events: auto;
}

.sidebar-nav-item {
  width: 100%;
  height: 38px;

  display: flex;
  align-items: center;
  gap: 11px;

  padding: 0 11px;

  border: 0;
  border-radius: 7px;

  background: transparent;
  color: #888;

  font-size: 12px;

