  color: #fff;
}

.sidebar-nav-item.active svg {
  color: #fff;
}


/* =========================================================
   SIDEBAR BOTTOM
========================================================= */

.sidebar-bottom {
  margin-top: auto;

  pointer-events: auto;
}

.backend-status {
  display: flex;
  align-items: center;
  gap: 9px;

  margin: 18px 6px 3px;
  padding: 11px 8px;

  border-top: 1px solid #202020;
}

.status-dot {
  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: var(--success);
}

.status-title {
  color: #aaa;

  font-size: 10px;
}

.status-url {
  margin-top: 2px;

  color: #555;

  font-size: 9px;
}


/* =========================================================
   MAIN AREA
========================================================= */

.main-area {
  position: relative;
  z-index: 1;

  flex: 1;
  min-width: 0;
  min-height: 0;

  display: flex;
  flex-direction: column;

  overflow: hidden;
}


/* =========================================================
   TOPBAR
========================================================= */

.topbar {
  /*
   * Floating overlay, not a flex sibling that reserves
   * its own row: it was previously in normal flow, which
   * pushed .graph-area's box down to start 48px below the
   * viewport top and clipped (overflow: hidden) anything
   * panned above that line — a node scrolled near the top
   * of the canvas would disappear completely, not just
   * visually sit under the bar. Taking the topbar out of
   * flow lets .graph-area fill the full height behind it,
   * so a node can now pan all the way to the top and still
   * be visible (through the transparent bar, or peeking
   * out from under the floating buttons) instead of being
   * cut off by a clipping boundary that used to sit right
   * at the bar's lower edge.
   */
  position: absolute;
  top: 0;
  left: 0;
  right: 0;

  z-index: 1000;

  width: 100%;
  height: 48px;
  min-height: 48px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 20px;

  border-bottom: none;

  background: transparent;

  pointer-events: none;
}

.topbar-left {
  position: relative;
  z-index: 1001;

  display: flex;
  align-items: center;
  gap: 6px;

  height: 34px;
  padding: 0 10px;

  border: 1px solid var(--border);
  border-radius: 8px;

  /*
   * Unlike the right-side buttons, the breadcrumb text
   * itself never had its own background — with the topbar
   * now floating over the (also full-height) canvas, that
   * meant a node panned up here rendered its name directly
   * behind "Graphs / demo", both illegible. One solid pill
   * around the whole left cluster fixes that the same way
   * the pre-existing Validate/Add Node/Execute pills always
   * did on the right.
   */
  background: #151515;

  pointer-events: auto;
}

.topbar-right {
  position: relative;
  z-index: 1001;

  display: flex;
  align-items: center;
  gap: 12px;

  pointer-events: auto;
}

.breadcrumb {
  display: flex;
  align-items: center;
  gap: 9px;

  min-width: 0;

  color: #ddd;

  font-size: 12px;
}

.breadcrumb-graph-name {
  overflow: hidden;

  max-width: 40vw;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.breadcrumb-muted {
  color: #666;
}

.breadcrumb-separator {
  color: #444;
}

.validation-status {
  display: flex;
  align-items: center;
  gap: 6px;

  color: #777;

  font-size: 11px;

  pointer-events: none;
}

.validation-status svg {
  color: var(--success);
}

.execute-button {
  position: relative;
  z-index: 1002;

  height: 34px;

  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;

  padding: 0 15px;

  border: 0;
  border-radius: 7px;

  background: #f5f5f5;
  color: #090909;

  font-size: 11px;
  font-weight: 600;

  transition:
    background 0.15s ease,
    opacity 0.15s ease,
    transform 0.1s ease;

  pointer-events: auto;
  user-select: none;
}

.execute-button:hover:not(:disabled) {
  background: #ffffff;
}

.execute-button:active:not(:disabled) {
  transform: translateY(1px);
}

.execute-button:disabled {
  opacity: 0.5;
}


/* =========================================================
   WORKSPACE
========================================================= */

.workspace {
  position: relative;
  z-index: 1;

  flex: 1;
  min-height: 0;

  display: flex;
  flex-direction: column;

  overflow: hidden;
}

.secondary-button,
.primary-button {
  position: relative;
  z-index: 22;

  height: 32px;

  display: flex;
  align-items: center;
  gap: 7px;

  padding: 0 12px;

  border-radius: 6px;

  font-size: 11px;

  pointer-events: auto;
}

.secondary-button {
  border: 1px solid var(--border);

  background: #151515;
  color: #aaa;
}

.secondary-button:hover {
  background: #1c1c1c;
  color: #ddd;
}

.primary-button {
  border: 1px solid #eee;

  background: #eee;
  color: #111;
}

.primary-button:hover {
  background: #fff;
}


/* =========================================================
   GRAPH AREA
========================================================= */

.graph-area {
  position: relative;
  z-index: 1;

  flex: 1;
  min-height: 0;

  overflow: hidden;

  background: #0b0b0b;
}

.graph-grid {
  position: absolute;
  inset: 0;

  z-index: 0;

  pointer-events: none;

  background-image:
    linear-gradient(
      rgba(255, 255, 255, 0.035) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(255, 255, 255, 0.035) 1px,
      transparent 1px
    );

  background-size: 32px 32px;
}


/* =========================================================
   REACT FLOW CONTAINER
========================================================= */

.torque-flow-container {
  position: absolute;
  inset: 0;

  z-index: 2;

  width: 100%;
  height: 100%;

  overflow: hidden;

  pointer-events: auto;
}

.torque-flow-container .react-flow {
  width: 100%;
  height: 100%;

  background: transparent;

  pointer-events: auto;
}

.torque-flow-container
  .react-flow__renderer {
  pointer-events: auto;
}

.torque-flow-container
  .react-flow__pane {
  pointer-events: auto;
}


/* =========================================================
   GRAPH NODES
========================================================= */

.graph-node {
  position: absolute;
  z-index: 2;

  width: 210px;

  display: flex;
  align-items: center;
  gap: 11px;

  padding: 12px;

  border: 1px solid #303030;
  border-radius: 9px;

  background: #151515;

  box-shadow:
    0 8px 25px rgba(0, 0, 0, 0.35);

  transition:
    border-color 0.15s ease,
    transform 0.15s ease;
}

.graph-node:hover {
  border-color: #555;

  transform: translateY(-1px);
}

.node-ceo {
  left: 24%;
  top: 23%;
}

.node-cto {
  left: 57%;
  top: 15%;
}

.node-cfo {
  left: 57%;
  top: 54%;
}

.node-it {
  left: 72%;
  top: 36%;
}

.node-icon {
  width: 36px;
  height: 36px;
  min-width: 36px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid #363636;
  border-radius: 7px;

  background: #202020;

  color: #ddd;

  font-size: 9px;
  font-weight: 700;
}

.node-name {
  color: #e5e5e5;

  font-size: 11px;
  font-weight: 600;
}

.node-role {
  margin-top: 3px;

  color: #666;

  font-size: 9px;
}


/* =========================================================
   CONNECTIONS
========================================================= */

.graph-connections {
  position: absolute;
  inset: 0;

  z-index: 1;

  width: 100%;
  height: 100%;

  pointer-events: none;
}

.graph-connections line {
  stroke: #444;

  stroke-width: 1.5;
}


/* =========================================================
   CANVAS CONTROLS
========================================================= */

.graph-controls {
  position: absolute;

  left: 18px;
  bottom: 18px;

  z-index: 50;

  display: flex;

  border: 1px solid #292929;
  border-radius: 7px;

  overflow: hidden;

  background: #111;

  pointer-events: auto;
}

.graph-controls button {
  width: 34px;
  height: 32px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 0;
  border-right: 1px solid #292929;

  background: transparent;
  color: #777;

  pointer-events: auto;
}

.graph-controls button:last-child {
  border-right: 0;
}

.graph-controls button:hover {
  background: #1b1b1b;

  color: #ddd;
}


/* =========================================================
   CANVAS INFO
========================================================= */

.canvas-info {
  position: absolute;

  right: 18px;
  bottom: 18px;

  z-index: 50;

  display: flex;
  gap: 7px;

  color: #555;

  font-size: 10px;

  pointer-events: none;
}


/* =========================================================
   REACT FLOW NODE
========================================================= */

.torque-flow-node {
  position: relative;

  min-width: 230px;

  display: flex;
  align-items: center;
  gap: 12px;

  padding: 12px;

  border: 1px solid #303030;
  border-radius: 10px;

  background: #151515;

  box-shadow:
    0 8px 30px rgba(0, 0, 0, 0.35);

  transition:
    border-color 0.15s ease,
    box-shadow 0.15s ease;
}

.torque-flow-node:hover {
  border-color: #555;
}

.torque-flow-node-selected {
  border-color: #888;

  box-shadow:
    0 0 0 1px #555,
    0 8px 30px rgba(0, 0, 0, 0.45);
}

.torque-node-avatar {
  width: 38px;
  height: 38px;
  min-width: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid #383838;
  border-radius: 8px;

  background: #202020;

  color: #ddd;

  font-size: 9px;
  font-weight: 700;
}

.torque-node-content {
  min-width: 0;
}

.torque-node-name {
  color: #eee;

  font-size: 12px;
  font-weight: 600;

  white-space: nowrap;
}

.torque-node-title {
  margin-top: 3px;

  color: #999;

  font-size: 10px;
}

.torque-node-role {
  margin-top: 3px;

  color: #5f5f5f;

  font-size: 9px;
}

.torque-node-add-button {
  position: absolute;
  bottom: -34px;
  left: 50%;

  transform: translateX(-50%);

  width: 24px;
  height: 24px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid #444;
  border-radius: 50%;

  background: #1a1a1a;
  color: #ccc;

  opacity: 0;

  /*
   * Pointer events stay enabled even while invisible
   * (unlike the old top-right placement). The button
   * sits a few pixels below the card now, outside its
   * box, so the mouse crosses a gap with nothing else
   * to hover on the way down — if this were pointer-
   * events: none while hidden, that gap would make the
   * button practically unreachable (hovering it can't
   * make it visible if hovering it is itself disabled).
   * Since it's still a DOM descendant of the wrapper,
   * the cursor landing here is what flips
   * .torque-flow-node-wrapper:hover on and fades it in.
   */

  transition:
    opacity 0.15s ease,
    background 0.15s ease,
    border-color 0.15s ease,
    color 0.15s ease;

  cursor: pointer;

  z-index: 10;
}

.torque-flow-node-wrapper:hover .torque-node-add-button {
  opacity: 1;
}

.torque-node-add-button:hover {
  background: #2a2a2a;
  border-color: #777;
  color: #fff;
}

.torque-edge-label {
  padding: 3px 6px;

  border: 1px solid #292929;
  border-radius: 4px;

  background: #111;

  color: #666;

  font-size: 8px;

  pointer-events: none;
}


/* =========================================================
   REACT FLOW HANDLES

   The clickable/draggable area (the `.react-flow__handle`
   element itself, since pointer-events is enabled directly
   on it) is deliberately much bigger than the visible dot —
   a 12px dot was a genuinely hard mouse target to land a
   drag on, especially when a node has both a source- and a
   target-typed handle stacked at the exact same spot on
   every side (see GraphNode.tsx). The dot stays visually
   small via the ::after pseudo-element, positioned with
   `inset` inside the now-larger, invisible (background:
   transparent) hit box.
========================================================= */

.torque-flow-container
  .react-flow__handle {
  width: 22px;
  height: 22px;

  border: 0;
  background: transparent;

  pointer-events: auto;
}

.torque-flow-container
  .react-flow__handle::after {
  content: "";

  position: absolute;
  inset: 5px;

  border-radius: 50%;

  background: #777;

  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.torque-flow-container
  .react-flow__handle:hover::after {
  background: #eee;

  transform: scale(1.15);
}

.torque-flow-container
  .react-flow__handle-connecting::after {
  background: #eee;
}

.torque-flow-container
  .react-flow__handle-valid::after {
  background: #4ade80;
}


/* =========================================================
   GRAPH LOADING
========================================================= */

.graph-loading,
.graph-empty {
  position: absolute;
  inset: 0;

  z-index: 40;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  gap: 10px;

  color: #666;

  font-size: 11px;

  pointer-events: none;
}

.graph-empty h2 {
  margin: 0;

  color: #aaa;

  font-size: 15px;
}

.graph-empty p {
  margin: 0;

  color: #555;

  font-size: 11px;
}

.loading-spinner {
  width: 20px;
  height: 20px;

  border: 2px solid #292929;
  border-top-color: #aaa;

  border-radius: 50%;

  animation: torque-spin 0.8s linear infinite;
}

@keyframes torque-spin {
  to {
    transform: rotate(360deg);
  }
}


/* =========================================================
   ERROR
========================================================= */

.error-banner {
  position: absolute;

  top: 78px;
  right: 24px;

  z-index: 200;

  display: flex;
  align-items: center;
  gap: 8px;

  padding: 9px 12px;

  border: 1px solid #3a2929;
  border-radius: 7px;

  background: #1b1212;

  color: #d88;

  font-size: 10px;

  pointer-events: auto;
}


/* =========================================================
   NODE INSPECTOR
========================================================= */

.node-inspector {
  position: absolute;

  /*
   * The topbar is now a floating overlay (see .topbar)
   * rather than a row that reserves its own height, so
   * this panel's old top: 20px landed right underneath
   * the Validate/Add Node/Execute buttons instead of
   * below them.
   */
  top: 64px;
  right: 20px;

  z-index: 100;

  width: 280px;

  padding: 16px;

  border: 1px solid #2d2d2d;
  border-radius: 10px;

  background: #111;

  box-shadow:
    0 15px 40px rgba(0, 0, 0, 0.45);

  pointer-events: auto;
}

.inspector-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  padding-bottom: 14px;

  border-bottom: 1px solid #222;
}

.inspector-label {
  color: #555;

  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.1em;
}

.inspector-header h2 {
  margin: 5px 0 0;

  color: #eee;

  font-size: 14px;
}

.inspector-close {
  width: 24px;
  height: 24px;

  border: 0;

  background: transparent;

  color: #666;

  font-size: 20px;

  pointer-events: auto;
}

.inspector-close:hover {
  color: #ddd;
}

.inspector-field {
  display: flex;
  flex-direction: column;
  gap: 5px;

  padding: 12px 0;

  border-bottom: 1px solid #1e1e1e;
}

.inspector-field span {
  color: #555;

  font-size: 9px;
}

.inspector-field strong {
  color: #bbb;

  font-size: 11px;
  font-weight: 500;
}

.inspector-field code {
  color: #777;

  font-size: 8px;

  word-break: break-all;
}


/* =========================================================
   REACT FLOW CONTROLS
========================================================= */

.torque-flow-container
  .react-flow__controls {
  z-index: 50;

  border: 1px solid #292929;
  border-radius: 6px;

  overflow: hidden;

  box-shadow: none;

  pointer-events: auto;
}

.torque-flow-container
  .react-flow__controls-button {
  width: 20px;
  height: 20px;

  border-bottom: 1px solid #292929;

  background: #111;

  fill: #777;

  pointer-events: auto;
}

.torque-flow-container
  .react-flow__controls-button svg {
  max-width: 9px;
  max-height: 9px;
}

.torque-flow-container
  .react-flow__controls-button:hover {
  background: #1b1b1b;

  fill: #ddd;
}

.torque-flow-container
  .react-flow__minimap {
  overflow: hidden;

  border: 1px solid #292929;
  border-radius: 6px;

  background: #111;
}


/* =========================================================
   MODALS
========================================================= */

.modal-backdrop {
  position: fixed;
  inset: 0;

  z-index: 1000;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 24px;

  background: rgba(0, 0, 0, 0.75);

  pointer-events: auto;
}

.modal {
  width: 100%;
  max-width: 480px;
  max-height: 90vh;

  display: flex;
  flex-direction: column;

  overflow: hidden;

  border: 1px solid #303030;
  border-radius: 12px;

  background: #111111;

  box-shadow: 0 25px 100px rgba(0, 0, 0, 0.8);
}

.modal-header {
  display: flex;
  flex-shrink: 0;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;

  padding: 16px 20px;

  border-bottom: 1px solid #242424;
}

.modal-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: #666;
}

.modal-header h2 {
  margin: 4px 0 0;

  font-size: 16px;
  font-weight: 600;
  color: #eee;
}

.modal-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 28px;
  height: 28px;

  border-radius: 6px;

  color: #777;
}

.modal-close:hover {
  background: #1d1d1d;
  color: #eee;
}

.modal-body {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 16px;

  min-height: 0;
  padding: 20px;

  overflow-y: auto;
}

.modal-body > label {
  display: flex;
  flex-direction: column;
  gap: 7px;

  font-size: 10px;
  color: #888;
}

.modal-body input {
  height: 38px;

  padding: 0 11px;

  border: 1px solid #2c2c2c;
  border-radius: 6px;

  outline: none;

  background: #181818;
  color: #eee;

  font-family: inherit;
  font-size: 11px;
}

.modal-body input::placeholder {
  color: #4d4d4d;
}

.modal-body input:focus {
  border-color: #555;
}

.modal-body input[type="checkbox"] {
  height: auto;

  width: 14px;
  height: 14px;

  accent-color: #eee;
}

.modal-footer {
  display: flex;
  flex-shrink: 0;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;

  padding: 14px 20px;

  border-top: 1px solid #242424;
}


/* =========================================================
   TEXTAREA + SELECT
========================================================= */

.modal-body textarea,
.modal-body select {
  width: 100%;

  padding: 9px 11px;

  border: 1px solid #2c2c2c;
  border-radius: 6px;

  outline: none;

  background: #181818;
  color: #eee;

  font-family: inherit;
  font-size: 11px;
}

.modal-body textarea {
  resize: vertical;

  min-height: 70px;
}

.modal-body textarea::placeholder {
  color: #4d4d4d;
}

.modal-body select {
  height: 38px;
}

.modal-body textarea:focus,
.modal-body select:focus {
  border-color: #555;
}


/* =========================================================
   EMPTY STATE
========================================================= */

.empty-icon {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-bottom: 4px;

  border: 1px solid #292929;
  border-radius: 9px;

  background: #151515;

  color: #777;
}


/* =========================================================
   ERROR CLOSE
========================================================= */

.error-close {
  width: 22px;
  height: 22px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-left: auto;

  border: 0;
  border-radius: 5px;

  background: transparent;

  color: #777;

  pointer-events: auto;
}

.error-close:hover {
  background: #251818;
  color: #ddd;
}


/* =========================================================
   INSPECTOR LIST
========================================================= */

.inspector-list {
  display: flex;
  flex-direction: column;
  gap: 5px;

  color: #888;

  font-size: 10px;
  line-height: 1.5;
}


/* =========================================================
   MODAL / OVERLAY SAFETY
========================================================= */

.fixed {
  pointer-events: auto;
}

.fixed button,
.fixed input,
.fixed textarea,
.fixed select {
  pointer-events: auto;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 900px) {
  .sidebar {
    width: 210px;
    min-width: 210px;
  }

  .topbar {
    padding: 0 16px;
  }

  .workspace-header {
    padding: 14px 16px;
  }
}

@media (max-width: 720px) {
  .sidebar {
    width: 190px;
    min-width: 190px;
  }

  .validation-status {
    display: none;
  }

  .workspace-header h1 {
    font-size: 15px;
  }
}

/* =========================================================
   MOBILE (<=768px)

   The sidebar switches from a permanent flex sibling to a
   fixed, off-canvas drawer (translateX, not unmounted, so
   its internal state/scroll position survives being
   toggled) opened via the topbar's hamburger button and
   closed by the backdrop or picking a nav item. The
   desktop collapse toggle is hidden here — a drawer that
   is either fully open or fully closed makes the collapsed
   "rail" state meaningless.
========================================================= */

@media (max-width: 768px) {
  .app-shell {
    overflow: hidden;
  }

  .sidebar,
  .sidebar-collapsed {
    position: fixed;
    top: 0;
    left: 0;

    z-index: 1000;

    width: 190px;
    min-width: 190px;
    height: 100dvh;

    padding: 20px 14px;

    transform: translateX(-100%);
    transition: transform 0.2s ease;

    box-shadow: 0 0 0 transparent;
  }

  .sidebar-mobile-open,
  .sidebar-collapsed.sidebar-mobile-open {
    transform: translateX(0);

    box-shadow: 20px 0 60px rgba(0, 0, 0, 0.5);
  }

  /* Collapsing doesn't make sense for a drawer that's
     either fully open or fully hidden. */
  .sidebar-collapsed .sidebar-logo,
  .sidebar-collapsed .new-graph-button,
  .sidebar-collapsed .sidebar-nav-item,
  .sidebar-collapsed .backend-status {
    justify-content: flex-start;
  }

  .sidebar .sidebar-toggle {
    display: none;
  }

  .mobile-menu-button {
    display: flex;
  }

  .topbar {
    padding: 0 12px;
  }

  .topbar-left {
    max-width: 62%;
  }

  /* "Graphs /" is redundant chrome once space is
     tight — the graph name + dropdown chevron is
     enough to identify the switcher. */
  .breadcrumb-muted,
  .breadcrumb-separator {
    display: none;
  }

  .breadcrumb-graph-name {
    max-width: 55vw;
  }

  .topbar-right {
    gap: 8px;
  }

  .topbar-right .secondary-button,
  .topbar-right .primary-button {
    padding: 0 10px;
  }

  .topbar-right .button-label {
    display: none;
  }

  .validation-status {
    display: none;
  }

  .node-inspector {
    top: auto;
    right: 0;
    bottom: 0;
    left: 0;

    width: 100%;

    max-height: 65vh;

    border-radius: 14px 14px 0 0;
    border-bottom: 0;

    overflow-y: auto;
  }

  .error-banner {
    top: auto;
    right: 12px;
    bottom: 12px;
    left: 12px;

    max-width: none;
  }

  .modal-backdrop {
    padding: 12px;
  }

  .modal {
    max-height: 88dvh;
    border-radius: 14px;
  }

  /* iOS Safari zooms the page in on focus of any input
     with a computed font-size under 16px — every form
     field in this app is well under that on desktop. */
  .modal-body input,
  .modal-body textarea,
  .modal-body select {
    font-size: 16px;
  }
}

@media (max-width: 480px) {
  .topbar-right .execute-button .button-label {
    display: none;
  }

  .canvas-info {
    right: 10px;
    bottom: 10px;

    font-size: 9px;
  }

  .graph-controls {
    left: 10px;
    bottom: 10px;
  }
}


/* =========================================================
   INFO TOOLTIP

   Trigger ("i" icon) stays inline; the bubble itself is
   rendered through a portal (see InfoTooltip.tsx) so it can
   escape modals with `overflow: hidden` and always sit
   above them. Visibility is controlled by React mounting it
   (not by CSS opacity/hover), so top/left/width come from
   the component's inline style and only stacking + look
   live here.
========================================================= */

.info-tooltip {
  position: relative;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  margin-left: 5px;

  vertical-align: middle;
}

.info-tooltip-icon {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 13px;
  height: 13px;

  border: 1px solid #4a4a4a;
  border-radius: 50%;

  color: #888;

  font-size: 9px;
  font-weight: 700;
  font-style: italic;

  cursor: help;

  user-select: none;
}

.info-tooltip-bubble {
  z-index: 10000;

  padding: 8px 10px;

  border: 1px solid #333;
  border-radius: 6px;

  background: #1c1c1c;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);

  color: #ccc;

  font-size: 10px;
  font-weight: 400;
  line-height: 1.5;

  pointer-events: none;
}

