                      selectedGraph.id
                    }
                    nodes={nodes}
                    relationships={
                      visibleRelationships
                    }
                    onNodeSelect={
                      setSelectedNode
                    }
                    onRelationshipCreated={
                      refreshRelationships
                    }
                    onRelationshipUpdated={
                      refreshRelationships
                    }
                    onDeleteRelationship={
                      removeRelationship
                    }
                    editRelationshipId={
                      pendingEditRelationshipId
                    }
                    onEditRelationshipConsumed={() =>
                      setPendingEditRelationshipId(
