                      New Graph
                    </button>
                  </div>
                )}

                <div className="canvas-info">
                  <span>
                    {nodes.length}{" "}
                    nodes
                  </span>

                  <span>
                    •
                  </span>

                  <span>
                    {
                      visibleRelationships.length
