          {/* ======================================
              EXECUTIONS VIEW
          ====================================== */}

          {activeView ===
            "Executions" && (
            <div className="flex h-full min-h-0 flex-col pt-16">
              <ViewHeader
                eyebrow="EXECUTIONS"
                title="Graph Executions"
                count={
                  executions.length
                }
                icon={
                  <Play
                    size={18}
                  />
                }
              />

              {error && (
                <div className="error-banner">
                  <AlertCircle
                    size={16}
                  />

                  <span>
                    {error}
                  </span>

                  <button
                    type="button"
                    className="error-close"
                    onClick={() =>
                      setError(
                        null,
                      )
                    }
                  >
                    <X size={14} />
                  </button>
                </div>
              )}

              <div className="flex min-h-0 flex-1 flex-col md:flex-row">
                {/* EXECUTION LIST

                    On mobile this is the whole page until an
                    execution is picked (see the `hidden`/`block`
                    toggle below) — a master/detail push, not a
                    cramped stacked list+detail. From md up both
                    panes are always visible side by side. */}

                <div
                  className={`${
                    selectedExecution
                      ? "hidden"
                      : "block"
                  } w-full flex-1 overflow-auto border-b border-[#242424] p-4 md:block md:w-[360px] md:flex-none md:border-b-0 md:border-r`}
                >
                  {executions.length ===
                  0 ? (
                    <div className="flex h-full items-center justify-center text-center">
                      <div>
                        <Play
                          size={
                            24
                          }
                          className="mx-auto text-[#444]"
                        />

                        <p className="mt-3 text-[11px] text-[#555]">
                          No executions yet.
                        </p>

                        <button
                          type="button"
                          className="primary-button mt-4"
                          onClick={() => {
                            setActiveView(
                              "Graph",
                            );
                          }}
                        >
                          <Network
                            size={
                              14
                            }
                          />

                          Open Graph
                        </button>
                      </div>
                    </div>
                  ) : (
                    <div className="space-y-2">
                      {executions.map(
                        (
                          execution,
                        ) => {
                          const active =
                            selectedExecution?.execution_id ===
                            execution.execution_id;

                          return (
                            <button
                              key={
                                execution.execution_id
                              }
                              type="button"
                              className={`w-full cursor-pointer rounded-lg border p-3 text-left transition ${
                                active
                                  ? "border-[#555] bg-[#191919]"
                                  : "border-[#292929] bg-[#111] hover:bg-[#151515]"
                              }`}
                              onClick={() => {
                                setSelectedExecution(
                                  execution,
                                );

                                setExecutionTrace(
                                  execution.routing_events ??
                                    [],
                                );

                                void refreshExecution(
                                  execution.execution_id,
                                );
                              }}
                            >
                              <div className="flex items-center justify-between gap-3">
                                <span className="truncate text-[10px] font-medium text-[#ddd]">
                                  {
                                    execution.question
                                  }
                                </span>

                                <StatusBadge
                                  status={
                                    execution.status
                                  }
                                />
                              </div>

                              <div className="mt-2 flex items-center justify-between gap-2 text-[8px] text-[#555]">
                                <span className="truncate">
                                  {
                                    execution.execution_id
                                  }
                                </span>

                                <span className="shrink-0">
                                  {formatFinishedAt(
                                    execution,
                                  )}
                                </span>
                              </div>
                            </button>
                          );
                        },
                      )}
                    </div>
                  )}
                </div>

                {/* EXECUTION DETAILS */}

                <div
                  className={`${
                    selectedExecution
                      ? "block"
                      : "hidden"
                  } min-w-0 flex-1 overflow-auto p-6 md:block`}
                >
                  {!selectedExecution ? (
                    <EmptyView
                      icon={
                        <Play
                          size={22}
                        />
                      }
                      title="Select an execution"
                      description="Choose an execution from the list to inspect its state and routing trace."
                    />
                  ) : (
                    <div className="max-w-4xl">
                      <button
                        type="button"
                        className="mb-4 flex items-center gap-1.5 text-[10px] font-medium text-[#999] hover:text-[#eee] md:hidden"
                        onClick={() =>
                          setSelectedExecution(
                            null,
                          )
                        }
                      >
                        <ArrowLeft
                          size={13}
                        />
                        Back to executions
                      </button>

                      <div className="flex flex-wrap items-start justify-between gap-4">
                        <div>
                          <div className="text-[9px] font-bold tracking-[0.12em] text-[#555]">
                            EXECUTION
                          </div>

                          <h2 className="mt-1 text-[18px] font-semibold text-[#eee]">
                            {
                              selectedExecution.question
                            }
                          </h2>

                          <div className="mt-2 text-[9px] text-[#555]">
                            {
                              selectedExecution.execution_id
                            }
                          </div>
                        </div>

                        <div className="flex items-center gap-2">
                          <StatusBadge
                            status={
                              selectedExecution.status
                            }
                          />

                          {(selectedExecution.status ===
                            "RUNNING" ||
                            selectedExecution.status ===
                              "PENDING") && (
                            <button
                              type="button"
                              className="secondary-button"
                              onClick={
                                handleStopExecution
                              }
                              disabled={
                                stoppingExecution
                              }
                            >
                              {stoppingExecution ? (
                                <Loader2
                                  size={
                                    14
                                  }
                                  className="animate-spin"
                                />
                              ) : (
                                <Square
                                  size={
                                    13
                                  }
                                />
                              )}

                              Stop
                            </button>
                          )}
                        </div>
                      </div>

                      <div className="mt-6 grid gap-3 sm:grid-cols-4">
                        <MetricCard
                          label="Start Node"
                          value={getNodeName(
                            selectedExecution.start_node_id,
                          )}
                        />

                        <MetricCard
                          label="Status"
                          value={
                            selectedExecution.status
                          }
                        />

                        <MetricCard
                          label="Routing Events"
                          value={String(
                            executionTrace.length,
                          )}
                        />

                        <MetricCard
                          label="Finished"
                          value={formatFinishedAt(
                            selectedExecution,
                          )}
                        />
                      </div>

                      <div className="mt-6 rounded-lg border border-[#292929]">
                        <div className="border-b border-[#292929] bg-[#151515] px-4 py-3">
                          <div className="text-[8px] font-bold tracking-[0.1em] text-[#555]">
                            ROUTING TRACE
                          </div>
                        </div>

                        <div className="divide-y divide-[#222]">
                          {executionTrace.length ===
                          0 ? (
                            <div className="p-6 text-[10px] text-[#555]">
                              No routing events recorded.
                            </div>
                          ) : (
                            executionTrace.map(
                              (
                                event,
                                index,
                              ) => (
                                <div
                                  key={`${event.relationship_id ?? "event"}-${index}`}
                                  className="grid grid-cols-[40px_1fr_auto] items-center gap-3 px-4 py-3"
                                >
                                  <div className="text-[9px] text-[#555]">
                                    {index +
                                      1}
                                  </div>

                                  <div>
                                    <div className="flex items-center gap-2 text-[10px] text-[#ddd]">
                                      <span>
                                        {
                                          getNodeName(
                                            event.from_node,
                                          )
                                        }
                                      </span>

                                      <ArrowRight
                                        size={
                                          12
                                        }
                                        className="text-[#555]"
                                      />

                                      <span>
                                        {
                                          getNodeName(
                                            event.to_node,
                                          )
                                        }
                                      </span>
                                    </div>

                                    <div className="mt-1 text-[8px] text-[#555]">
                                      {
                                        event.reason
                                      }
                                    </div>
                                  </div>

                                  <span
                                    className={`text-[8px] font-semibold ${
                                      event.allowed
                                        ? "text-green-400"
                                        : "text-red-400"
                                    }`}
                                  >
                                    {event.allowed
                                      ? "ALLOWED"
                                      : "BLOCKED"}
                                  </span>
                                </div>
                              ),
                            )
                          )}
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {/* ======================================
              HISTORY VIEW
          ====================================== */}

          {activeView ===
            "History" && (
            <div className="flex h-full flex-col overflow-y-auto pt-16">
              <ViewHeader
                eyebrow="HISTORY"
                title="Execution History"
                count={
                  executions.length
                }
                icon={
                  <History
                    size={18}
                  />
                }
              />

              <div className="grid gap-3 p-6 sm:grid-cols-2 xl:grid-cols-3">
                <MetricCard
                  label="Total Executions"
                  value={String(
                    executions.length,
                  )}
                />

                <MetricCard
                  label="Completed"
                  value={String(
                    completedExecutions,
                  )}
                />

                <MetricCard
                  label="Graph Nodes"
                  value={String(
                    nodes.length,
                  )}
                />
              </div>

              <div className="px-6 pb-6">
                {executions.length ===
                0 ? (
                  <EmptyView
                    icon={
                      <History
                        size={22}
                      />
                    }
                    title="No execution history"
                    description="Run the graph to create execution history."
                  />
                ) : (
                  <div className="overflow-x-auto rounded-lg border border-[#292929]">
                    <div className="min-w-[760px] grid grid-cols-[1fr_140px_120px_170px_180px] border-b border-[#292929] bg-[#151515] px-4 py-3 text-[8px] font-bold tracking-[0.1em] text-[#555]">
                      <span>
                        QUESTION
                      </span>

                      <span>
                        STATUS
                      </span>

                      <span>
                        START NODE
                      </span>

                      <span>
                        FINISHED
                      </span>

                      <span>
                        EXECUTION ID
                      </span>
                    </div>

                    {executions.map(
                      (
                        execution,
                      ) => (
                        <button
                          key={
                            execution.execution_id
                          }
                          type="button"
                          className="grid w-full min-w-[760px] cursor-pointer grid-cols-[1fr_140px_120px_170px_180px] items-center border-b border-[#222] px-4 py-3 text-left last:border-b-0 hover:bg-[#141414]"
                          onClick={() => {
                            setSelectedExecution(
                              execution,
                            );

                            setExecutionTrace(
                              execution.routing_events ??
                                [],
                            );

                            setActiveView(
                              "Executions",
                            );

                            void refreshExecution(
                              execution.execution_id,
                            );
                          }}
                        >
                          <span className="truncate pr-4 text-[10px] text-[#ddd]">
                            {
                              execution.question
                            }
                          </span>

                          <span>
                            <StatusBadge
                              status={
                                execution.status
                              }
                            />
                          </span>

                          <span className="truncate text-[9px] text-[#777]">
                            {getNodeName(
                              execution.start_node_id,
                            )}
                          </span>

                          <span className="truncate text-[9px] text-[#777]">
                            {formatFinishedAt(
                              execution,
                            )}
                          </span>

                          <span className="truncate text-[8px] text-[#555]">
                            {
                              execution.execution_id
                            }
                          </span>
                        </button>
                      ),
                    )}
                  </div>
                )}
              </div>
            </div>
          )}

          {/* ======================================
              SETTINGS
          ====================================== */}

          {activeView ===
            "Settings" && (
            <div className="flex h-full flex-col pt-16">
              <ViewHeader
                eyebrow="SETTINGS"
                title="Workspace Settings"
                icon={
                  <Network
                    size={18}
                  />
                }
              />

              <div className="max-w-2xl p-6">
                <div className="rounded-lg border border-[#292929] bg-[#111] p-5">
                  <div className="text-[9px] font-bold tracking-[0.1em] text-[#555]">
                    BACKEND
                  </div>

                  <div className="mt-3 flex items-center gap-2">
                    <span className="h-2 w-2 rounded-full bg-green-400" />

                    <span className="text-[11px] text-[#ddd]">
                      Backend connected
                    </span>
                  </div>

                  <div className="mt-2 text-[9px] text-[#555]">
                    http://127.0.0.1:8000
                  </div>
                </div>

                <div className="mt-3 rounded-lg border border-[#292929] bg-[#111] p-5">
                  <div className="text-[9px] font-bold tracking-[0.1em] text-[#555]">
                    CURRENT GRAPH
                  </div>

                  <div className="mt-2 text-[12px] text-[#ddd]">
                    {selectedGraph?.name ??
                      "No graph selected"}
                  </div>

                  <div className="mt-3 grid grid-cols-3 gap-3">
                    <MetricCard
                      label="Nodes"
                      value={String(
                        nodes.length,
                      )}
                    />

                    <MetricCard
                      label="Relationships"
                      value={String(
                        visibleRelationships.length,
                      )}
                    />

                    <MetricCard
                      label="Protocols"
                      value={String(
                        protocols.length,
                      )}
                    />
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* ======================================
              MODALS
          ====================================== */}

          {showNewGraphModal && (
            <div
              className="modal-backdrop"
              onMouseDown={
                closeNewGraphModal
              }
            >
              <div
                className="modal"
                onMouseDown={(
                  event,
                ) =>
                  event.stopPropagation()
                }
              >
                <div className="modal-header">
                  <div>
                    <div className="modal-label">
                      WORKSPACE
                    </div>

                    <h2>
                      Create New Graph
                    </h2>
                  </div>

                  <button
                    type="button"
                    className="modal-close"
                    onClick={
                      closeNewGraphModal
                    }
                  >
                    <X size={17} />
                  </button>
                </div>

                <div className="modal-body">
                  <label>
                    Graph Name

                    <input
                      value={
                        graphName
                      }
                      onChange={(
                        event,
                      ) =>
                        setGraphName(
                          event.target
                            .value,
                        )
                      }
                      placeholder="e.g. Apple Organization"
                      autoFocus
                    />
                  </label>

                  <label>
                    Target Organization

                    <input
                      value={
                        targetOrganization
                      }
                      onChange={(
                        event,
                      ) =>
                        setTargetOrganization(
                          event.target
                            .value,
                        )
                      }
                      placeholder="e.g. Apple"
                    />
                  </label>

                  <label>
                    Description

                    <textarea
                      value={
                        graphDescription
                      }
                      onChange={(
                        event,
                      ) =>
                        setGraphDescription(
                          event.target
                            .value,
                        )
                      }
                      placeholder="Describe this organization graph..."
                      rows={3}
                    />
                  </label>
                </div>

                <div className="modal-footer">
                  <button
                    type="button"
                    className="secondary-button"
                    onClick={
                      closeNewGraphModal
                    }
                    disabled={
                      creatingGraph
                    }
                  >
                    Cancel
                  </button>

                  <button
                    type="button"
                    className="primary-button"
                    onClick={
                      handleCreateGraph
                    }
                    disabled={
                      creatingGraph ||
                      !graphName.trim()
                    }
                  >
                    {creatingGraph
                      ? "Creating..."
                      : "Create Graph"}
                  </button>
                </div>
              </div>
            </div>
          )}

          {showAddNodeModal && (
            <div
              className="modal-backdrop"
              onMouseDown={
                closeAddNodeModal
              }
            >
              <div
                className="modal"
                onMouseDown={(
                  event,
                ) =>
                  event.stopPropagation()
                }
              >
                <div className="modal-header">
                  <div>
                    <div className="modal-label">
                      ORGANIZATION
                    </div>

                    <h2>
                      Add Node
                    </h2>
                  </div>

                  <button
                    type="button"
                    className="modal-close"
                    onClick={
                      closeAddNodeModal
                    }
                  >
                    <X size={17} />
                  </button>
                </div>

                <div className="modal-body">
                  <label>
                    Name

                    <input
                      value={
                        nodeName
                      }
                      onChange={(
                        event,
                      ) =>
                        setNodeName(
                          event.target
                            .value,
                        )
                      }
                      placeholder="e.g. Chief Technology Officer"
                      autoFocus
                    />
                  </label>

                  <label>
                    Title

                    <input
                      value={
                        nodeTitle
                      }
                      onChange={(
                        event,
                      ) =>
                        setNodeTitle(
                          event.target
                            .value,
                        )
                      }
                      placeholder="e.g. CTO"
                    />
                  </label>

                  <label>
                    Role

                    <input
                      value={
                        nodeRole
                      }
                      onChange={(
                        event,
                      ) =>
                        setNodeRole(
                          event.target
                            .value,
                        )
                      }
                      placeholder="e.g. Technology"
                    />
                  </label>

                  <label>
                    Parent Position

                    <select
                      value={
                        nodeParentId
                      }
                      onChange={(
                        event,
                      ) =>
                        setNodeParentId(
                          event.target
                            .value,
                        )
                      }
                    >
                      <option value="">
                        No parent
                      </option>

                      {nodes.map(
                        (
                          node,
                        ) => (
                          <option
                            key={
                              node.id
                            }
                            value={
                              node.id
                            }
                          >
                            {
                              node.name
                            }
                          </option>
                        ),
                      )}
                    </select>
                  </label>
                </div>

                <div className="modal-footer">
                  <button
                    type="button"
                    className="secondary-button"
                    onClick={
                      closeAddNodeModal
                    }
                    disabled={
                      creatingNode
                    }
                  >
                    Cancel
                  </button>

                  <button
                    type="button"
                    className="primary-button"
                    onClick={
                      handleCreateNode
                    }
                    disabled={
                      creatingNode ||
                      !nodeName.trim()
                    }
                  >
                    {creatingNode
                      ? "Creating..."
                      : "Create Node"}
                  </button>
                </div>
              </div>
            </div>
          )}

          {showEditNodeModal && (
            <div
              className="modal-backdrop"
              onMouseDown={closeEditNodeModal}
            >
              <div
                className="modal"
                onMouseDown={(event) =>
                  event.stopPropagation()
                }
              >
                <div className="modal-header">
                  <div>
                    <div className="modal-label">
                      ORGANIZATION
                    </div>

                    <h2>Edit Node</h2>
                  </div>

                  <button
                    type="button"
                    className="modal-close"
                    onClick={closeEditNodeModal}
                    disabled={updatingNode}
                  >
                    <X size={17} />
                  </button>
                </div>

                <div className="modal-body">
                  <label>
                    Name

                    <input
                      value={nodeName}
                      onChange={(event) =>
                        setNodeName(
                          event.target.value,
                        )
                      }
                      placeholder="e.g. Chief Technology Officer"
                      autoFocus
                    />
                  </label>

                  <label>
                    Title

                    <input
                      value={nodeTitle}
                      onChange={(event) =>
                        setNodeTitle(
                          event.target.value,
                        )
                      }
                      placeholder="e.g. CTO"
                    />
                  </label>

                  <label>
                    Role

                    <input
                      value={nodeRole}
                      onChange={(event) =>
                        setNodeRole(
                          event.target.value,
                        )
                      }
                      placeholder="e.g. Technology"
                    />
                  </label>

                  <label>
                    Parent Position

                    <select
                      value={nodeParentId}
                      onChange={(event) =>
                        setNodeParentId(
                          event.target.value,
                        )
                      }
                    >
                      <option value="">
                        No parent
                      </option>

                      {nodes
                        .filter(
                          (node) =>
                            node.id !==
                            editingNodeId,
                        )
                        .map((node) => (
                          <option
                            key={node.id}
                            value={node.id}
                          >
                            {node.name}
                          </option>
                        ))}
                    </select>
                  </label>

                  {error && (
                    <div className="rounded-md border border-red-900/50 bg-red-950/30 px-3 py-2 text-[10px] text-red-400">
                      {error}
                    </div>
                  )}
                </div>

                <div className="modal-footer">
                  <button
                    type="button"
                    className="secondary-button"
                    onClick={closeEditNodeModal}
                    disabled={updatingNode}
                  >
                    Cancel
                  </button>

                  <button
                    type="button"
                    className="primary-button"
                    onClick={handleUpdateNode}
                    disabled={
                      updatingNode ||
                      !nodeName.trim()
                    }
                  >
                    {updatingNode
                      ? "Saving..."
                      : "Save Changes"}
                  </button>
                </div>
              </div>
            </div>
          )}

          {showExecuteModal && (
            <div
              className="modal-backdrop"
              onMouseDown={
                closeExecuteModal
              }
            >
              <div
                className="modal"
                onMouseDown={(event) =>
                  event.stopPropagation()
                }
              >
                <div className="modal-header">
                  <div>
                    <div className="modal-label">
                      EXECUTION
                    </div>

                    <h2>
                      Execute Graph
                    </h2>
                  </div>

                  <button
                    type="button"
                    className="modal-close"
                    onClick={
                      closeExecuteModal
                    }
                    disabled={executing}
                  >
                    <X size={17} />
                  </button>
                </div>

                <div className="modal-body">
                  <label>
                    Start Node

                    <select
                      value={
                        executeStartNodeId
                      }
                      onChange={(event) =>
                        setExecuteStartNodeId(
                          event.target
                            .value,
                        )
                      }
                    >
                      {nodes.map(
                        (node) => (
                          <option
                            key={node.id}
                            value={
                              node.id
                            }
                          >
                            {node.name}
                          </option>
                        ),
                      )}
                    </select>
                  </label>

                  <label>
                    Question

                    <textarea
                      value={
                        executeQuestion
                      }
                      onChange={(event) =>
                        setExecuteQuestion(
                          event.target
                            .value,
                        )
                      }
                      placeholder="What question should the organization answer?"
                      rows={3}
                      autoFocus
                    />
                  </label>

                  {error && (
                    <div className="rounded-md border border-red-900/50 bg-red-950/30 px-3 py-2 text-[10px] text-red-400">
                      {error}
                    </div>
                  )}
                </div>

                <div className="modal-footer">
                  <button
                    type="button"
                    className="secondary-button"
                    onClick={
                      closeExecuteModal
                    }
                    disabled={executing}
                  >
                    Cancel
                  </button>

                  <button
                    type="button"
                    className="primary-button"
                    onClick={handleExecute}
                    disabled={
                      executing ||
                      !executeQuestion.trim() ||
                      !executeStartNodeId
                    }
                  >
                    {executing ? (
                      <Loader2
                        size={15}
                        className="animate-spin"
                      />
                    ) : (
                      <Play
                        size={15}
                        fill="currentColor"
                      />
                    )}

                    {executing
                      ? "Executing..."
                      : "Execute"}
                  </button>
                </div>
              </div>
            </div>
          )}

        </div>
      </section>
    </main>
  );
}

// ============================================
// SMALL UI COMPONENTS
// ============================================

function ViewHeader({
  eyebrow,
  title,
  count,
  icon,
}: {
  eyebrow: string;
  title: string;
  count?: number;
  icon?: React.ReactNode;
}) {
  return (
    <div className="border-b border-[#242424] px-6 py-4">
      <div className="flex items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          {icon && (
            <div className="flex h-8 w-8 items-center justify-center rounded-md border border-[#292929] bg-[#151515] text-[#777]">
              {icon}
            </div>
          )}

          <div>
            <div className="text-[9px] font-bold tracking-[0.12em] text-[#555]">
              {eyebrow}
            </div>

            <h2 className="mt-1 text-[16px] font-semibold text-[#eee]">
