          Edit Relationship
        </button>

        <button
          type="button"
          className="h-7 flex-1 rounded-md border border-red-900/60 bg-red-950/20 text-[10px] font-medium text-red-400 hover:bg-red-950/40"
          onClick={onDelete}
        >
          Delete
        </button>
      </div>
    </div>,
    document.body,
  );
}

