          <Trash2 size={12} />
        </button>
      </div>

      <div className="mt-4 grid grid-cols-2 gap-2">
        <Permission
          label="Send"
          enabled={protocol.can_send}
        />

        <Permission
          label="Receive"
          enabled={protocol.can_receive}
